const seed={student:null,fees:{total:0,paid:0,entries:[]},courses:[],classes:[],students:[],attendanceRecords:[],academic:[],results:[],studentFees:{},schedule:[],classSchedules:{},notifications:[],events:[],announcements:[]};

// EduIQ cloud sync: one shared application state for the same institution across devices.
const SUPABASE_URL='https://pejsubxbgbcsfvjwsyes.supabase.co';
const SUPABASE_ANON_KEY='sb_publishable_62lxPzFVXCvGBWzON-mzRg_t0r5jW-Wg';
const CLOUD_STATE_ID='eduiq-main';
const supabaseClient=(window.supabase&&window.supabase.createClient)?window.supabase.createClient(SUPABASE_URL,SUPABASE_ANON_KEY):null;
let cloudReady=false,cloudBusy=false,cloudTimer=null;
function cloudPayload(d){const x=JSON.parse(JSON.stringify(normalize(d))); delete x.student; return x}
async function cloudRead(){if(!supabaseClient)return null;try{const {data,error}=await supabaseClient.from('eduiq_app_state').select('payload,updated_at').eq('id',CLOUD_STATE_ID).maybeSingle();if(error){console.warn('EduIQ cloud read:',error.message);return null}return data||null}catch(e){console.warn('EduIQ cloud read failed:',e);return null}}
async function cloudWrite(d){if(!supabaseClient||cloudBusy)return;cloudBusy=true;try{const payload=cloudPayload(d);const {error}=await supabaseClient.from('eduiq_app_state').upsert({id:CLOUD_STATE_ID,payload,updated_at:new Date().toISOString()},{onConflict:'id'});if(error)console.warn('EduIQ cloud write:',error.message);else cloudReady=true}catch(e){console.warn('EduIQ cloud write failed:',e)}finally{cloudBusy=false}}
function queueCloudWrite(d){clearTimeout(cloudTimer);cloudTimer=setTimeout(()=>cloudWrite(d),250)}
async function hydrateFromCloud({preferCloud=true}={}){if(!supabaseClient)return false;const row=await cloudRead();if(row?.payload&&preferCloud){const local=get();const merged=normalize({...row.payload,student:local.student});localStorage[STORAGE_KEY]=JSON.stringify(merged);cloudReady=true;return true}if(!row?.payload){await cloudWrite(get());return true}return false}
async function prepareCloud(){if(!supabaseClient)return;await hydrateFromCloud({preferCloud:true});}

const normalize=(raw)=>{const d=raw||JSON.parse(JSON.stringify(seed));d.student=d.student||null;d.courses=Array.isArray(d.courses)?d.courses:[];d.schedule=Array.isArray(d.schedule)?d.schedule:[];d.classSchedules=d.classSchedules&&typeof d.classSchedules==='object'?d.classSchedules:{};d.classes=Array.isArray(d.classes)?d.classes.map(c=>({...c,students:Number(c.students??0),subjects:Number(c.subjects??0),attendance:Number(c.attendance??0)})):[];d.students=Array.isArray(d.students)?d.students:[];d.attendanceRecords=Array.isArray(d.attendanceRecords)?d.attendanceRecords:[];d.academic=Array.isArray(d.academic)?d.academic:[];d.results=Array.isArray(d.results)?d.results:[];d.studentFees=d.studentFees&&typeof d.studentFees==='object'?d.studentFees:{};d.notifications=Array.isArray(d.notifications)?d.notifications:[];d.events=Array.isArray(d.events)?d.events:[];d.announcements=Array.isArray(d.announcements)?d.announcements:[];d.attendance=d.attendance&&typeof d.attendance==='object'?d.attendance:{overall:0,subjects:[]};d.attendance.overall=Number(d.attendance.overall||0);d.attendance.subjects=Array.isArray(d.attendance.subjects)?d.attendance.subjects:[];d.students.forEach(st=>{if(!d.studentFees[st.id])d.studentFees[st.id]={total:0,entries:[],assigned:false};d.studentFees[st.id].total=Number(d.studentFees[st.id].total||0);d.studentFees[st.id].entries=Array.isArray(d.studentFees[st.id].entries)?d.studentFees[st.id].entries:[];if(typeof d.studentFees[st.id].assigned!=='boolean')d.studentFees[st.id].assigned=d.studentFees[st.id].total>0});const main=d.student?d.students.find(x=>x.admissionNo===d.student.admissionNo):null;d.fees={total:Number(main?d.studentFees[main.id].total:0),entries:main?(d.studentFees[main.id].entries||[]):[]};d.fees.paid=d.fees.entries.reduce((a,x)=>a+Number(x.amount||0),0);return d};
const LEGACY_KEYS=['eduiq_v10_clean','eduiq_v9','eduiq_v8'];
LEGACY_KEYS.forEach(k=>localStorage.removeItem(k));
const STORAGE_KEY='eduiq_v11_clean';
const state={view:'login',loginMode:'student',page:'dashboard',student:false,admin:false};
const get=()=>{try{return normalize(JSON.parse(localStorage[STORAGE_KEY]||JSON.stringify(seed)))}catch(e){localStorage.removeItem(STORAGE_KEY);return normalize(seed)}};
const save=d=>{const normalized=normalize(d);localStorage[STORAGE_KEY]=JSON.stringify(normalized);queueCloudWrite(normalized);return normalized};
if(!localStorage[STORAGE_KEY])save(seed);

const defaultStudents=[];
const defaultAttendanceRecords=[];
const icon=(x)=>`<span class="icon">${x}</span>`;const money=n=>'₹'+Number(n).toLocaleString('en-IN');
const studentFee=(d,id)=>d.studentFees?.[id]||{total:0,entries:[],assigned:false};
const feePaid=(d,id)=>studentFee(d,id).entries.reduce((a,x)=>a+Number(x.amount||0),0);
const currentStudentRecord=(d)=>d.student?(d.students||[]).find(s=>s.admissionNo===d.student.admissionNo):null;
function toast(m){const e=document.getElementById('toast');e.textContent=m;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2400)}
function login(mode='student'){const admin=mode==='admin';return `<div class="login-page"><div class="login-ambient"><div class="login-grid"></div><div class="login-glow glow-one"></div><div class="login-glow glow-two"></div><div class="login-brand"><span class="brand-orbit logo-orbit-image"><img src="assets/eduiq-logo.png" alt="EduIQ"></span><div><b>EduIQ</b><small>LEARNING MANAGEMENT SYSTEM</small></div></div><div class="login-showcase"><div class="showcase-kicker">${admin?'INSTITUTION CONTROL CENTER':'YOUR ACADEMIC COMMAND CENTER'}</div><h1>${admin?'Run the institution\nwith clarity.':'Everything academic.\nBeautifully organized.'}</h1><p>${admin?'Students, courses, classes, attendance, academics and offline fee records in one controlled workspace.':'Your timetable, attendance, results, study material and fee status — available in one calm, focused workspace.'}</p><div class="showcase-metrics"><div><strong>01</strong><span>Unified academic workspace</span></div><div><strong>02</strong><span>Institution-issued access</span></div><div><strong>03</strong><span>Built for Supabase</span></div></div><div class="showcase-orbit"><div class="orbit-ring ring-a"></div><div class="orbit-ring ring-b"></div><div class="orbit-core"><span> E </span></div><div class="float-chip chip-a">ATTENDANCE <b>READY</b></div><div class="float-chip chip-b">FEES <b>TRACKED</b></div><div class="float-chip chip-c">ACADEMICS <b>READY</b></div></div></div><div class="login-side-note"><span class="status-dot"></span> Secure institution-controlled access <span>•</span> ${admin?'Administrator workspace':'Student workspace'}</div></div><div class="login-panel"><div class="login-panel-top"><div class="mini-brand"><span class="mini-brand-mark"><img src="assets/eduiq-logo.png" alt="EduIQ"></span><div><b>EduIQ</b><small>LMS</small></div></div><div class="mode-switch"><button class="${!admin?'active':''}" onclick="showLogin('student')">Student</button><button class="${admin?'active':''}" onclick="showLogin('admin')">Admin</button></div></div><div class="login-card"><div class="login-card-head"><span class="login-icon">${admin?'⌘':'↗'}</span><div><div class="eyebrow">${admin?'ADMINISTRATOR ACCESS':'STUDENT ACCESS'}</div><h2>${admin?'Welcome back.':'Welcome back.'}</h2><p>${admin?'Sign in to manage your institution.':'Use the Admission No. and password issued by your institution administrator.'}</p></div></div><form onsubmit="event.preventDefault();doLogin('${mode}')"><label>${admin?'Admin ID':'Admission No.'}<div class="input-wrap"><input id="loginId" required value="" placeholder="${admin?'Administrator ID':'EDUIQ/2026/0001'}" autocomplete="username"></div></label><label>Password<div class="input-wrap"><input id="loginPass" required type="password" value="" placeholder="Student@0001" autocomplete="current-password"><button type="button" class="password-toggle" onclick="togglePassword()" aria-label="Show or hide password">◉</button></div></label><div class="login-options"><label class="check"><input type="checkbox"> Keep me signed in</label><button type="button" class="linkbtn" onclick="toast('Please contact your institution administrator to reset credentials.')">Forgot password?</button></div><button class="login-submit" type="submit"><span>${admin?'Open Control Center':'Enter EduIQ LMS'}</span><b>↗</b></button></form><div class="credential-note"><span>i</span><div><b>Institution-issued credentials</b><small>${admin?'Administrator access is restricted to authorized institution staff.':'Your Admission No. and initial password are provided by your institution administrator.'}</small></div></div></div><div class="login-footer"><span>EduIQ LMS · 2026</span><span>Secure access</span></div></div></div>`}
function togglePassword(){const e=document.getElementById('loginPass');if(e)e.type=e.type==='password'?'text':'password'}
function shell(admin=false){const studentNav=[['dashboard','Dashboard','⌂'],['schedule','Schedule','▦'],['assignments','Assignments','✓'],['homework','Homework','✎'],['calendar','Calendar','□'],['materials','Study Materials','▤'],['exams','Exams & Date Sheet','▣'],['results','Results','◒'],['attendance','Attendance','◔'],['fees','Fees','₹'],['notifications','Notifications','◌'],['profile','My Profile','◎']];const adminNav=[['admin','Overview','⌂'],['students','Students','♙'],['courses','Courses','◈'],['classes','Classes','▦'],['academics','Academics','◈'],['attendance','Attendance','◔'],['fees','Fees & Deposits','₹'],['announcements','Announcements','◉'],['reports','Reports','◒'],['history','History','↺'],['profile','My Profile','◎']];const navButton=x=>`<button class="nav ${state.page===x[0]?'active':''}" onclick="go('${x[0]}')">${icon(x[2])}<span>${x[1]}</span></button>`;return `<div class="app"><aside class="side"><div class="brand"><span class="logo-mark"><img src="assets/eduiq-logo.png" alt="EduIQ"></span><div><b>EduIQ</b><small>${admin?'ADMIN CONSOLE':'LEARNING SYSTEM'}</small></div></div><div class="side-scroll">${admin?`<div class="side-section"><div class="side-label">OVERVIEW</div><nav>${navButton(adminNav[0])}</nav></div><div class="side-section section-divider"><div class="side-label">PEOPLE & STRUCTURE</div><nav>${adminNav.slice(1,5).map(navButton).join('')}</nav></div><div class="side-section section-divider"><div class="side-label">OPERATIONS</div><nav>${adminNav.slice(5,10).map(navButton).join('')}</nav></div>`:`<div class="side-section"><div class="side-label">WORKSPACE</div><nav>${studentNav.slice(0,5).map(navButton).join('')}</nav></div><div class="side-section section-divider"><div class="side-label">ACADEMICS</div><nav>${studentNav.slice(5,10).map(navButton).join('')}</nav></div>`}</div></aside><main class="main"><header class="top"><button class="mobile-menu" onclick="document.querySelector('.side').classList.toggle('open')">☰</button><div class="top-heading"><small>${admin?'ADMINISTRATION':'STUDENT PORTAL'}</small><b>${admin?'EduIQ Control Center':pageTitle()}</b></div><div class="top-right"><button class="circle" onclick="toggleTheme()" aria-label="Toggle dark or light mode" title="Toggle theme">◐</button><button class="header-logout" onclick="logout()" aria-label="Sign out" title="Sign out"><span>↪</span><b>Sign out</b></button><button class="circle notification-trigger" onclick="openNotificationCenter()" aria-label="Notifications">◌<span class="notification-badge"></span></button><div class="top-user" onclick="go('profile')"><span class="top-avatar">${admin?(localStorage.adminAvatar?`<img src="${localStorage.adminAvatar}" alt="Administrator">`:'AD'):(get().student.avatar?`<img src="${get().student.avatar}" alt="Profile photo">`:profileInitials(get().student.name))}</span><div><b>${admin?'Administrator':get().student.name}</b><small>${admin?'Institution admin':get().student.admissionNo}</small></div></div></div></header><section class="main-content" id="screen"></section></main></div>`}
function pageTitle(){return ({dashboard:'Dashboard',schedule:'Schedule',assignments:'Assignments',homework:'Homework',calendar:'Calendar',materials:'Study Materials',exams:'Exams & Date Sheet',attendance:'Attendance',fees:'Fees',results:'Results',notifications:'Notifications',profile:'My Profile'})[state.page]||'Dashboard'}
function go(p){state.page=p;render();document.querySelector('.side')?.classList.remove('open')}
function studentAcademicScope(d,me){const cls=(d.classes||[]).find(c=>c.id===me?.classId);return {classId:me?.classId||'',className:String(cls?.name||me?.className||'').trim().toLowerCase(),courseId:me?.courseId||cls?.courseId||''}}
function academicPublished(x){return !x.status||String(x.status).trim().toLowerCase()==='published'}
function academicVisibleToStudent(d,x,scope){if(!academicPublished(x))return false;if(!x.classId)return true;if(scope.classId&&String(x.classId)===String(scope.classId))return true;const xc=(d.classes||[]).find(c=>String(c.id)===String(x.classId));const xname=String(x.className||xc?.name||'').trim().toLowerCase();return !!(scope.className&&xname&&scope.className===xname)}
function studentAcademicItems(d,me,type){const scope=studentAcademicScope(d,me);return (d.academic||[]).filter(x=>x.type===type&&academicVisibleToStudent(d,x,scope)).sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0))}
function studentScreen(){const d=get();const me=currentStudentRecord(d);if(!me){state.student=false;return `<div class="empty panel"><div class="empty-icon">◎</div><h2>Student record unavailable</h2><p>Please sign in again or contact your institution administrator.</p><button class="btn primary" onclick="logout()">Return to login</button></div>`}const mf=studentFee(d,me.id),att=(d.attendanceRecords||[]).find(x=>x.studentId===me.id)||d.attendance||{overall:0,subjects:[]};if(state.page==='homework')return resourcePage('Homework','Homework','Latest published homework appears first.','Homework');if(state.page==='calendar')return resourcePage('Calendar','Calendar','Latest published events appear first.','Events & Calendar');if(state.page==='dashboard'){const assignments=studentAcademicItems(d,me,'Assignments');const homework=studentAcademicItems(d,me,'Homework');const latest=[...assignments,...homework].sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0)).slice(0,4);return `<div class="welcome"><div><div class="eyebrow">STUDENT PORTAL</div><h1>Welcome, ${me.name.split(' ')[0]}.</h1><p>${me.course||'Course not assigned'} · ${me.year||'Year not assigned'} · ${me.roll||'Roll not assigned'}</p></div><button class="btn primary" onclick="go('profile')">Complete profile ${icon('→')}</button></div><div class="stats4"><div class="statcard"><small>Attendance</small><strong>${att.overall}%</strong><span class="positive">${att.overall>=75?'Good standing':'Needs attention'}</span></div><div class="statcard"><small>Pending assignments</small><strong>${assignments.length}</strong><span>${assignments.length?'Latest work available':'No assignments yet'}</span></div><div class="statcard"><small>Academic records</small><strong>${(d.results||[]).filter(x=>x.studentId===me.id).length}</strong><span>${(d.results||[]).length?'Published records':'No results published'}</span></div><div class="statcard"><small>Fees deposited</small><strong>${mf.total?Math.round(feePaid(d,me.id)/mf.total*100):0}%</strong><span>${money(feePaid(d,me.id))} / ${money(mf.total)}</span></div></div><div class="dash-grid"><div class="panel"><div class="panel-title"><div><small>WEEKLY RHYTHM</small><h2>Schedule</h2></div><button class="linkbtn" onclick="go('schedule')">View all →</button></div>${renderStudentSchedulePreview(d,me)}</div><div class="panel"><div class="panel-title"><div><small>LATEST ACADEMIC WORK</small><h2>Assignments & homework</h2></div><button class="linkbtn" onclick="go('assignments')">View assignments →</button></div>${latest.length?latest.map(x=>`<div class="notice"><span class="notice-dot">•</span><div><b>${x.title}</b><small>${x.type} · ${formatDate(x.createdAt)}</small></div></div>`).join(''):`<div class="empty-inline"><b>No academic work published yet.</b><span>Your institution will publish assignments and homework here.</span></div>`}</div></div><div class="dash-grid"><div class="panel"><div class="panel-title"><div><small>ACADEMIC HEALTH</small><h2>Attendance by subject</h2></div><button class="linkbtn" onclick="go('attendance')">Full report →</button></div>${att.subjects.length?att.subjects.map(x=>`<div class="metric"><div><b>${x[0]}</b><span>${x[1]}%</span></div><div class="progress"><i style="width:${x[1]}%"></i></div></div>`).join(''):`<div class="empty-inline"><b>No attendance recorded yet.</b><span>Your institution will publish attendance here.</span></div>`}</div><div class="panel"><div class="panel-title"><div><small>FINANCE</small><h2>Fee deposit</h2></div><button class="linkbtn" onclick="go('fees')">Details →</button></div><div class="fee-chart"><div class="donut big" style="--p:${mf.total?feePaid(d,me.id)/mf.total*100:0}%"><span>${mf.total?Math.round(feePaid(d,me.id)/mf.total*100):0}%<small>deposited</small></span></div><div><strong>${money(feePaid(d,me.id))}</strong><p>recorded of ${money(mf.total)}</p><span class="pill green">${money(Math.max(0,mf.total-feePaid(d,me.id)))} remaining</span></div></div></div></div>`}if(state.page==='assignments')return resourcePage('Assignments','Assignments','Latest published assignments appear first.','Assignments');if(state.page==='fees')return feePage();if(state.page==='profile')return profilePage();if(state.page==='attendance')return attendancePage();if(state.page==='schedule')return schedulePage();if(state.page==='results')return resultsPage();if(state.page==='exams')return resourcePage('Exams & Date Sheet','Exams & Date Sheet','Latest published examination documents appear first.','Exams & Date Sheets');if(state.page==='materials')return resourcePage('Study Materials','Study Materials','Latest published resources appear first.','Study Materials');if(state.page==='notifications')return tablePage('Notifications','Academic events and reminders.',['Notification','Category','Time','Status'],(d.notifications||[]).map(x=>[x.title||'',x.category||'Notice',x.time||'',x.status||'Read']));return `<div class="empty panel"><div class="empty-icon">◎</div><h2>${pageTitle()}</h2><p>This module is ready for institution-published records.</p></div>`}
function renderStudentSchedulePreview(d,me){const rows=(((d.classSchedules||{})[me.classId])||d.schedule||[]).slice().sort((a,b)=>String(a.time||'').localeCompare(String(b.time||'')));return rows.length?`<div class="timeline">${rows.slice(0,5).map(r=>`<div class="tline"><b>${r.time}</b><i></i><div><strong>${(r.days||[]).find(x=>x&&x!=='—')||'No class'}</strong><span>Weekly timetable</span></div></div>`).join('')}</div>`:`<div class="empty-inline"><b>No timetable published yet.</b><span>Your administrator controls the class schedule.</span></div>`}
function formatDate(v){if(!v)return 'Recently';const d=new Date(v);return Number.isNaN(d.getTime())?'Recently':d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}
function schedulePage(){const d=get(),sid=((d.students||[]).find(s=>s.admissionNo===d.student.admissionNo)||{}).classId||'',rows=(sid&&d.classSchedules?.[sid])||d.schedule||[],items=(d.academic||[]).filter(x=>x.type==='Timetable'&&(x.status==='Published'||!x.status)&&(x.classId===sid||!x.classId));return `<div class="page-head"><div><div class="eyebrow">WEEKLY RHYTHM</div><h1>Schedule</h1><p>Your class timetable is published and controlled by the institution.</p></div></div><div class="panel table-panel schedule-live"><div class="schedule-live-head"><div><small>CLASS SCHEDULE</small><h2>${d.classes.find(c=>c.id===sid)?.name||'Current class'}</h2></div><span class="pill blue">Admin managed</span></div><table><thead><tr><th>Time</th><th>Monday</th><th>Tuesday</th><th>Wednesday</th><th>Thursday</th><th>Friday</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.time}</td>${r.days.map(x=>`<td><span class="pill ${x==='Break'?'amber':'blue'}">${x}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div>${items.length?`<div class="panel resource-strip"><div class="panel-title"><div><small>PUBLISHED FILES</small><h2>Timetable documents</h2></div></div><div class="resource-inline">${items.map(resourceCard).join('')}</div></div>`:''}<div class="schedule-help"><span>↗</span><div><b>Need a change?</b><small>Your timetable is changed by an administrator under <strong>Academics → Timetable</strong>. Updates appear here after publication.</small></div></div></div>`}
function resultsPage(){const d=get(),mine=(d.results||[]).filter(r=>r.studentId===((d.students||[]).find(s=>s.admissionNo===d.student.admissionNo)||{}).id);if(!mine.length)return `<div class="page-head"><div><div class="eyebrow">PERFORMANCE</div><h1>Results</h1><p>Semester performance published by your institution.</p></div></div><div class="empty panel"><div class="empty-icon">◒</div><h2>No results published yet</h2><p>Your academic results will appear here when the administrator publishes them.</p></div>`;const rows=mine.map(r=>[r.subject,String(r.max),String(r.obtained),r.grade,String(r.point)]);return `<div class="page-head"><div><div class="eyebrow">PERFORMANCE</div><h1>Results</h1><p>Semester performance at a glance.</p></div></div>${tablePage('', '', ['Subject','Maximum','Obtained','Grade','Grade Point'],rows)}`}
function simpleStudentPage(kicker,title,desc,items){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div></div><div class="subject-grid">${items.map((x,i)=>`<div class="panel metric-card"><div><b>${x}</b><span class="pill ${i===0?'blue':'green'}">${i===0?'Upcoming':'Scheduled'}</span></div><p class="muted">Class feed managed by your institution.</p><button class="linkbtn" onclick="toast('This item will open from your class feed.')">View details →</button></div>`).join('')}</div>`}
function resourcePage(kicker,title,desc,type){const d=get(),me=currentStudentRecord(d),items=me?studentAcademicItems(d,me,type):[];return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div></div><div class="resource-grid">${items.length?items.map(resourceCard).join(''):`<div class="panel empty"><div class="empty-icon">▤</div><h2>No published ${title.toLowerCase()} yet.</h2><p>Your institution will publish content here.</p></div>`}</div>`}
function resourceCard(x){const a=x.attachment;return `<article class="panel resource-card"><div class="resource-meta"><span class="pill blue">${x.type}</span><span>${new Date(x.createdAt||Date.now()).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}</span></div><h2>${x.title}</h2><p>${x.details||'Published by your institution.'}</p>${a?(a.type.startsWith('image/')?`<img class="resource-image" src="${a.data}" alt="${a.name}">`:`<div class="file-preview"><span>PDF</span><b>${a.name}</b><small>${(a.size/1024/1024).toFixed(2)} MB</small></div><div class="resource-actions"><button class="btn" onclick="viewAttachment(${x.id})">View</button><button class="btn primary" onclick="downloadAttachment(${x.id})">Download</button></div>`):''}${a&&a.type.startsWith('image/')?`<div class="resource-actions"><button class="btn" onclick="viewAttachment(${x.id})">View image</button><button class="btn primary" onclick="downloadAttachment(${x.id})">Download image</button></div>`:''}</article>`}
function viewAttachment(id){const d=get(),x=d.academic.find(a=>a.id===id);if(!x?.attachment)return;const a=x.attachment;if(a.type.startsWith('image/'))document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">ATTACHMENT PREVIEW</div><h2>${a.name}</h2><img class="attachment-preview" src="${a.data}" alt="${a.name}"><div class="modal-actions"><button class="btn" onclick="document.getElementById('modal').remove()">Close</button><button class="btn primary" onclick="downloadAttachment(${id})">Download</button></div></div></div>`);else window.open(a.data,'_blank','noopener')}
function downloadAttachment(id){const d=get(),x=d.academic.find(a=>a.id===id);if(!x?.attachment)return;const a=x.attachment;const link=document.createElement('a');link.href=a.data;link.download=a.name;document.body.appendChild(link);link.click();link.remove()}

function attendancePage(){
 const d=get(),me=currentStudentRecord(d);
 if(!me)return `<div class="panel empty"><div class="empty-icon">◔</div><h2>Attendance unavailable</h2><p>Your student record could not be loaded.</p></div>`;
 const rec=(d.attendanceRecords||[]).find(x=>x.studentId===me.id)||{overall:0,subjects:[]};
 const subjects=Array.isArray(rec.subjects)?rec.subjects:[];
 const overall=Math.max(0,Math.min(100,Number(rec.overall||0)));
 return `<div class="page-head"><div><div class="eyebrow">ACADEMIC HEALTH</div><h1>Attendance</h1><p>Your institution-published attendance record.</p></div></div><div class="panel attendance-summary"><div class="attendance-head"><div class="donut huge" style="--p:${overall}%"><span>${overall}%<small>overall</small></span></div><div><small class="eyebrow">STATUS</small><h2>${overall>=75?'Good standing':'Needs attention'}</h2><p class="muted">Required minimum: 75%</p></div></div></div><div class="subject-grid">${subjects.length?subjects.map(x=>{const name=Array.isArray(x)?x[0]:(x.subject||x.name||'Subject'),val=Number(Array.isArray(x)?x[1]:(x.percentage??x.value??0));return `<div class="panel metric-card"><div><b>${esc(name)}</b><strong>${val}%</strong></div><div class="progress"><i style="width:${Math.max(0,Math.min(100,val))}%"></i></div><small>${val>=75?'Healthy attendance':'Approaching threshold'}</small></div>`}).join(''):`<div class="panel empty"><div class="empty-icon">◔</div><h2>No attendance recorded yet</h2><p>Your institution will publish your attendance here once records are entered.</p></div>`}</div>`;
}
function feePage(){
 const d=get(),me=currentStudentRecord(d);
 if(!me)return `<div class="panel empty"><div class="empty-icon">₹</div><h2>Fee center unavailable</h2><p>Your student record could not be loaded.</p></div>`;
 const f=studentFee(d,me.id),total=Number(f.total||0),paid=feePaid(d,me.id),remaining=Math.max(total-paid,0),pct=total?Math.min(100,paid/total*100):0;
 const entries=(f.entries||[]).slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
 return `<div class="page-head"><div><div class="eyebrow">FINANCE</div><h1>Fee center</h1><p>Your course fee is assigned by the institution. Only recorded offline deposits appear here.</p></div></div><div class="fee-overview"><div class="panel fee-main"><div class="donut huge" style="--p:${pct}%"><span>${Math.round(pct)}%<small>deposited</small></span></div><div><small class="eyebrow">TOTAL COURSE FEE</small><h2>${money(total)}</h2><p>${money(paid)} deposited · ${money(remaining)} remaining</p><div class="progress wide"><i style="width:${pct}%"></i></div></div></div><div class="panel"><small class="eyebrow">COURSE</small><h2>${esc(me.course||d.courses?.find(c=>c.id===me.courseId)?.name||'Not assigned')}</h2><p>${esc(me.year||'')}</p><span class="pill green">Institution maintained</span></div></div><div class="panel table-panel"><div class="panel-title"><div><small>OFFLINE RECORDS</small><h2>Payment history</h2></div><span class="pill green">Admin maintained</span></div><table><thead><tr><th>Date</th><th>Receipt ID</th><th>Amount</th><th>Method</th><th>Status</th></tr></thead><tbody>${entries.length?entries.map(e=>`<tr><td>${esc(e.date||'—')}</td><td>${esc(e.id||'—')}</td><td><b>${money(e.amount||0)}</b></td><td>${esc(e.method||'Offline')}</td><td><span class="pill green">Recorded</span></td></tr>`).join(''):`<tr><td colspan="5"><div class="empty"><div class="empty-icon">₹</div><h2>No payments recorded</h2><p>Your institution has not recorded an offline deposit yet.</p></div></td></tr>`}</tbody></table></div>`;
}
function profileInitials(name){return String(name||'ST').trim().split(/\s+/).filter(Boolean).map(x=>x[0]).join('').slice(0,2).toUpperCase()||'ST'}
function profilePage(){
 const d=get(),me=currentStudentRecord(d);
 if(!me){return `<div class="page-head"><div><div class="eyebrow">STUDENT PORTAL</div><h1>My Profile</h1><p>Your institution-issued academic identity and account settings.</p></div></div><div class="panel empty"><div class="empty-icon">◎</div><h2>Profile unavailable</h2><p>Your student record could not be loaded. Please sign in again or contact your administrator.</p><button class="btn primary" onclick="logout()">Return to login</button></div>`}
 const initials=profileInitials(me.name),course=me.course||d.courses?.find(c=>c.id===me.courseId)?.name||'Not assigned',cls=d.classes?.find(c=>c.id===me.classId)?.name||'Not assigned';
 return `<div class="page-head"><div><div class="eyebrow">STUDENT PORTAL</div><h1>My Profile</h1><p>Manage your contact details and account security. Institution-issued academic details are controlled by your administrator.</p></div></div>
 <div class="profile-grid">
  <div class="panel identity"><div class="profile-avatar profile-avatar-photo">${me.avatar?`<img src="${me.avatar}" alt="Profile photo">`:`<span>${initials}</span>`}</div><label class="photo-upload"><input type="file" accept="image/png,image/jpeg,image/webp" onchange="handleProfilePhoto('student',this)">Change photo</label><h2>${me.name||'Student'}</h2><p>${me.admissionNo||'Admission number unavailable'}</p><div class="identity-list"><span><b>Admission No.</b><b>${me.admissionNo||'—'}</b></span><span><b>Course</b><b>${course}</b></span><span><b>Class</b><b>${cls}</b></span><span><b>Roll No.</b><b>${me.roll||'—'}</b></span></div></div>
  <div>
   <div class="panel"><div class="panel-title"><div><small>PERSONAL DETAILS</small><h2>Contact information</h2></div><span class="pill green">Student editable</span></div><form onsubmit="event.preventDefault();saveStudentProfile()"><div class="form-grid"><label>Full name<input id="profileName" value="${esc(me.name||'')}" readonly><small class="field-hint">Name is maintained by the institution.</small></label><label>Admission No.<input value="${esc(me.admissionNo||'')}" readonly><small class="field-hint">Institution-issued identifier.</small></label><label>Phone number<input id="profilePhone" type="tel" value="${esc(me.phone||'')}" placeholder="Enter phone number"></label><label>Email address<input id="profileEmail" type="email" value="${esc(me.email||'')}" placeholder="Enter email address"></label><label>Date of birth<input id="profileDob" type="date" value="${esc(me.dob||'')}"></label><label>Address<input id="profileAddress" value="${esc(me.address||'')}" placeholder="Enter address"></label></div><div class="modal-actions"><button class="btn primary">Save profile</button></div></form></div>
   <div class="panel security-panel"><div class="panel-title"><div><small>ACCOUNT SECURITY</small><h2>Password</h2></div><span class="pill blue">Private</span></div><p class="muted">Change the password used to sign in to EduIQ LMS. Your institution can still manage your academic identity.</p><button class="btn" onclick="openPasswordModal('student')">Change password</button></div>
  </div>
 </div>`
}
function adminProfilePage(){
 const name=localStorage.adminName||'Administrator',email=localStorage.adminEmail||'',initials=profileInitials(name);
 return `<div class="page-head"><div><div class="eyebrow">ADMINISTRATION</div><h1>My Profile</h1><p>Manage administrator contact details and account security.</p></div></div><div class="profile-grid"><div class="panel identity"><div class="profile-avatar profile-avatar-photo">${localStorage.adminAvatar?`<img src="${localStorage.adminAvatar}" alt="Profile photo">`:`<span>${initials}</span>`}</div><label class="photo-upload"><input type="file" accept="image/png,image/jpeg,image/webp" onchange="handleProfilePhoto('admin',this)">Change photo</label><h2>${esc(name)}</h2><p>Institution administrator</p><div class="identity-list"><span><b>Admin ID</b><b>admin</b></span><span><b>Role</b><b>Administrator</b></span><span><b>Access</b><b>Control Center</b></span></div></div><div><div class="panel"><div class="panel-title"><div><small>ADMINISTRATOR DETAILS</small><h2>Contact information</h2></div><span class="pill green">Editable</span></div><form onsubmit="event.preventDefault();saveAdminProfile()"><div class="form-grid"><label>Display name<input id="adminProfileName" value="${esc(name)}" required></label><label>Email address<input id="adminProfileEmail" type="email" value="${esc(email)}" placeholder="admin@example.com"></label></div><div class="modal-actions"><button class="btn primary">Save profile</button></div></form></div><div class="panel security-panel"><div class="panel-title"><div><small>ACCOUNT SECURITY</small><h2>Password</h2></div><span class="pill blue">Private</span></div><p class="muted">Change the administrator password used for Control Center access.</p><button class="btn" onclick="openPasswordModal('admin')">Change password</button></div></div></div>`
}
function esc(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;')}
function saveStudentProfile(){const d=get(),me=currentStudentRecord(d);if(!me)return toast('Student record unavailable.');me.phone=document.getElementById('profilePhone')?.value.trim()||'';me.email=document.getElementById('profileEmail')?.value.trim()||'';me.dob=document.getElementById('profileDob')?.value||'';me.address=document.getElementById('profileAddress')?.value.trim()||'';d.student={...d.student,...me};save(d);toast('Profile updated successfully.');go('profile')}function handleProfilePhoto(role,input){const file=input?.files?.[0];if(!file)return;if(file.size>2*1024*1024)return toast('Profile photo must be under 2 MB.');if(!file.type.startsWith('image/'))return toast('Please choose an image file.');const reader=new FileReader();reader.onload=()=>{if(role==='student'){const d=get(),me=currentStudentRecord(d);if(!me)return;me.avatar=reader.result;d.student={...d.student,...me};save(d)}else localStorage.adminAvatar=reader.result;toast('Profile photo updated.');render()};reader.readAsDataURL(file)}
function saveAdminProfile(){localStorage.adminName=document.getElementById('adminProfileName')?.value.trim()||'Administrator';localStorage.adminEmail=document.getElementById('adminProfileEmail')?.value.trim()||'';toast('Administrator profile updated successfully.');go('profile')}
function adminScreen(){const d=get();if(state.page==='profile')return adminProfilePage();if(state.page==='admin'){const students=(d.students||[]).length,classes=(d.classes||[]).length,courses=(d.courses||[]).length;const deposits=Object.values(d.studentFees||{}).flatMap(f=>f.entries||[]).reduce((a,e)=>a+Number(e.amount||0),0),billed=Object.values(d.studentFees||{}).reduce((a,f)=>a+Number(f.total||0),0),att=(d.attendanceRecords||[]).filter(x=>typeof x.overall==='number'),avg=att.length?Math.round(att.reduce((a,x)=>a+Number(x.overall||0),0)/att.length):0;return `<div class="welcome"><div><div class="eyebrow">INSTITUTION OVERVIEW</div><h1>Control center.</h1><p>Your LMS is ready. Add courses, classes and students to build the institution.</p></div><button class="btn primary" onclick="go('courses')">Create course ${icon('+')}</button></div><div class="stats4"><div class="statcard"><small>Total students</small><strong>${students}</strong><span>${students?'Active records':'No students added yet'}</span></div><div class="statcard"><small>Active classes</small><strong>${classes}</strong><span>${courses} courses</span></div><div class="statcard"><small>Fee collection</small><strong>${money(deposits)}</strong><span>${money(billed)} billed</span></div><div class="statcard"><small>Attendance</small><strong>${avg}%</strong><span>${att.length?'Calculated from records':'No attendance recorded'}</span></div></div><div class="admin-grid"><div class="panel empty"><div class="empty-icon">◈</div><h2>Build your academic structure</h2><p>Create a course first, then add classes, subjects and students. Nothing is preloaded.</p><button class="btn primary" onclick="go('courses')">Create your first course</button></div><div class="panel empty"><div class="empty-icon">◔</div><h2>No analytics yet</h2><p>Fees, attendance and academic charts will populate automatically as you enter real records.</p></div></div>`;}if(state.page==='students')return adminStudents();if(state.page==='courses')return adminCourses();if(state.page==='classes')return adminClasses();if(state.page==='fees')return adminFees();if(state.page==='academics')return adminAcademics();if(state.page==='attendance')return adminAttendance();if(state.page==='history')return adminHistory();if(state.page==='reports')return `<div class="page-head"><div><div class="eyebrow">REPORTING</div><h1>Reports</h1><p>Operational insights for institutional decisions.</p></div></div><div class="admin-grid"><div class="panel"><h2>Academic performance</h2><div class="admin-bars tall">${[72,78,82,75,88,91,86].map((x,i)=>`<i style="height:${x}%"><span>${['P','Ph','A','B','C','D','E'][i]}</span></i>`).join('')}</div></div><div class="panel"><h2>Quick exports</h2><div class="quick-actions"><button class="btn" onclick="toast('CSV export will connect to Supabase.')">Export students CSV</button><button class="btn" onclick="toast('PDF report will connect to Supabase.')">Generate fee report</button><button class="btn" onclick="toast('Attendance export will connect to Supabase.')">Attendance report</button></div></div></div>`;return tablePage('Announcements','Publish institutional communication.',['Title','Category','Audience','Status'],(d.announcements||[]).map(x=>[x.title||'',x.category||'',x.audience||'All students',x.status||'Draft']))}
function adminStudents(){const d=get();const rows=(d.students||[]).map(x=>{const f=studentFee(d,x.id),paid=feePaid(d,x.id),total=Number(f.total||0);return `<tr><td><b>${x.name}</b><small class="cell-sub">${x.roll||'—'}</small></td><td>${x.admissionNo}</td><td>${x.course} · ${x.year}</td><td>${money(paid)} / ${money(total)}</td><td><span class="pill green">Active</span></td><td><button class="linkbtn" onclick="openStudentModal('${x.id}')">Edit</button><button class="danger-link inline" onclick="deleteStudent('${x.id}')">Delete</button></td></tr>`}).join('');return `<div class="page-head"><div><div class="eyebrow">STUDENT DIRECTORY</div><h1>Students</h1><p>Create institution-issued credentials and manage academic identity.</p></div><button class="btn primary" onclick="openStudentModal()">+ Add student</button></div><div class="panel table-panel"><table><thead><tr><th>Student</th><th>Admission No.</th><th>Class</th><th>Course fee / Paid</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows}</tbody></table></div>`}
function nextStudentSerial(d){const nums=(d.students||[]).map(s=>String(s.admissionNo||'').match(/^EDUIQ[\/\-]2026[\/\-](\d{1,})$/i)).filter(Boolean).map(m=>Number(m[1])||0);return Math.max(0,...nums)+1}function studentCredentials(d,existing){if(existing)return {admissionNo:existing.admissionNo||'',password:existing.password||''};const n=nextStudentSerial(d),serial=String(n).padStart(4,'0');return {admissionNo:`EDUIQ/2026/${serial}`,password:`Student@${serial}`}}
function openStudentModal(editId=''){const d=get(),existing=editId?(d.students||[]).find(x=>x.id===editId):null;const creds=studentCredentials(d,existing);const fee=existing?studentFee(d,existing.id):{total:0,entries:[],assigned:false};const courseId=existing?.courseId||'';const course=courseId?d.courses.find(c=>c.id===courseId):null;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">${existing?'EDIT STUDENT':'NEW STUDENT'}</div><h2>${existing?'Update academic identity':'Issue portal access'}</h2><p class="muted">Choose the master course first. Its configured fee becomes the student's default course fee; you can override the individual fee when required.</p><form onsubmit="event.preventDefault();saveStudent('${editId}')"><div class="form-grid"><label>Student name<input id="sname" required value="${existing?.name||''}" placeholder="Full name"></label><label>Admission No.<input id="sadmission" required value="${creds.admissionNo}" ${existing?'':'readonly'}><small class="field-hint">${existing?'Institution-issued admission number.':'Automatically generated in sequence.'}</small></label><label>Initial password<input id="spassword" required value="${creds.password}" ${existing?'':'readonly'}><small class="field-hint">${existing?'Current institution-issued password.':'Automatically generated in sequence.'}</small></label><label>Course<select id="scourse" onchange="updateStudentCourseDefaults()"><option value="">Select course</option>${(d.courses||[]).map(c=>`<option value="${c.id}" ${courseId===c.id?'selected':''}>${c.name} · ${money(c.fee||0)}</option>`).join('')}</select></label><label>Class<select id="sclass">${(d.classes||[]).filter(c=>!courseId||c.courseId===courseId).map(c=>`<option value="${c.id}" ${(existing?.classId||'')===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Roll number<input id="sroll" value="${existing?.roll||'24DP1050'}"></label><label>Assigned course fee<input id="scoursefee" type="number" min="0" required value="${Number(fee.total||course?.fee||0)}" placeholder="Course fee"><small class="field-hint">Defaults from the selected course. Admin may override for an individual student.</small></label></div><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">${existing?'Save changes':'Create & issue access'}</button></div></form></div></div>`)}
function updateStudentCourseDefaults(){const d=get(),cid=document.getElementById('scourse').value,c=d.courses.find(x=>x.id===cid);const fee=document.getElementById('scoursefee');if(c)fee.value=Number(c.fee||0);const sel=document.getElementById('sclass');sel.innerHTML=(d.classes||[]).filter(x=>x.courseId===cid).map(x=>`<option value="${x.id}">${x.name}</option>`).join('');}
function saveStudent(editId){const d=get(),id=editId||('STU-'+Date.now()),classId=document.getElementById('sclass').value,courseId=document.getElementById('scourse').value,course=d.courses.find(c=>c.id===courseId),student={id,name:document.getElementById('sname').value.trim(),admissionNo:document.getElementById('sadmission').value.trim(),password:document.getElementById('spassword').value,course:course?.name||'',courseId,year:(d.classes.find(c=>c.id===classId)?.name||'').replace(/^.*—\s*/,'')||'First Year',classId,roll:document.getElementById('sroll').value.trim(),mustChangePassword:editId?(d.students.find(x=>x.id===editId)?.mustChangePassword||false):true};if(!courseId)return toast('Select a course before creating or assigning the student.');if(!classId)return toast('Assign the student to a class under the selected course.');if(editId){const i=d.students.findIndex(x=>x.id===editId);if(i>=0){const oldClass=d.students[i].classId;d.students[i]={...d.students[i],...student};if(oldClass!==classId){const oldC=d.classes.find(c=>c.id===oldClass),newC=d.classes.find(c=>c.id===classId);if(oldC)oldC.students=Math.max(0,Number(oldC.students||0)-1);if(newC)newC.students=Number(newC.students||0)+1;}}}else{d.students.push(student);const cls=d.classes.find(c=>c.id===classId);if(cls)cls.students=Number(cls.students||0)+1;d.attendanceRecords=d.attendanceRecords||[];d.attendanceRecords.push({studentId:id,studentName:student.name,admissionNo:student.admissionNo,classId,courseId,subjects:[],overall:0});}d.studentFees=d.studentFees||{};d.studentFees[id]=d.studentFees[id]||{total:0,entries:[],assigned:false};d.studentFees[id].total=Number(document.getElementById('scoursefee').value||0);d.studentFees[id].courseId=courseId;d.studentFees[id].assigned=d.studentFees[id].total>0;save(d);document.getElementById('modal')?.remove();toast(editId?'Student updated.':'Student created and assigned to course.');go('students')}
function deleteStudent(id){const d=get(),st=d.students.find(x=>x.id===id);if(!st)return;if(!confirm(`Delete ${st.name} (${st.admissionNo})? This removes the student from the local demo, including attendance, results and fee records.`))return;const cls=d.classes.find(c=>c.id===st.classId);if(cls)cls.students=Math.max(0,Number(cls.students||0)-1);d.students=d.students.filter(x=>x.id!==id);delete d.studentFees?.[id];d.attendanceRecords=(d.attendanceRecords||[]).filter(x=>x.studentId!==id);d.results=(d.results||[]).filter(x=>x.studentId!==id);save(d);toast('Student deleted.');go('students')}
function adminCourses(){const d=get(),courses=d.courses||[];return `<div class="page-head"><div><div class="eyebrow">ACADEMIC CATALOG</div><h1>Courses</h1><p>Create the master course first, define its fee and academic details, then attach classes and students to it.</p></div><button class="btn primary" onclick="openCourseModal()">+ Create course</button></div><div class="class-grid">${courses.length?courses.map(c=>{const cls=(d.classes||[]).filter(x=>x.courseId===c.id),sts=(d.students||[]).filter(x=>x.courseId===c.id),recs=(d.attendanceRecords||[]).filter(r=>sts.some(s=>s.id===r.studentId));const att=recs.length?Math.round(recs.reduce((a,r)=>a+Number(r.overall||0),0)/recs.length):0;return `<div class="panel class-card"><span class="class-icon">◈</span><div class="course-code">${c.code||'COURSE'}</div><h2>${c.name}</h2><p class="muted">${c.description||'No course description yet.'}</p><div><b>${money(c.fee||0)} fee</b><span>${cls.length} classes</span><span>${sts.length} students</span><span>${att}% attendance</span></div><div class="class-actions"><button class="linkbtn" onclick="openCourseManager('${c.id}')">Manage course →</button><button class="danger-link" onclick="deleteCourse('${c.id}')">Delete course</button></div></div>`}).join(''):`<div class="panel empty"><div class="empty-icon">◈</div><h2>No courses created</h2><p>Create a course with its details and fee before assigning classes or students.</p><button class="btn primary" onclick="openCourseModal()">Create your first course</button></div>`}</div>`}
function openCourseModal(editId=''){const d=get(),c=editId?(d.courses||[]).find(x=>x.id===editId):null;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">${c?'EDIT COURSE':'NEW COURSE'}</div><h2>${c?'Update course details':'Create course'}</h2><p class="muted">Define the academic program first. Its fee becomes the default fee when students are assigned to this course.</p><form onsubmit="event.preventDefault();saveCourse('${editId}')"><div class="form-grid"><label>Course name<input id="courseName" required value="${c?.name||''}" placeholder="D.Pharm"></label><label>Course code<input id="courseCode" value="${c?.code||''}" placeholder="DPHARM"></label><label>Course fee<input id="courseFee" type="number" min="0" required value="${c?.fee??0}" placeholder="85000"></label><label>Duration<input id="courseDuration" value="${c?.duration||''}" placeholder="2 Years"></label><label>Academic session<input id="courseSession" value="${c?.session||'2026–27'}" placeholder="2026–27"></label><label>Status<select id="courseStatus"><option ${c?.status==='inactive'?'':'selected'}>Active</option><option ${c?.status==='inactive'?'selected':''}>Inactive</option></select></label><label class="full">Description<textarea id="courseDescription" rows="4" placeholder="Course overview, eligibility, structure...">${c?.description||''}</textarea></label></div><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">${c?'Save changes':'Create course'}</button></div></form></div></div>`)}
function saveCourse(editId){const d=get(),id=editId||'COURSE-'+Date.now(),course={id,name:document.getElementById('courseName').value.trim(),code:document.getElementById('courseCode').value.trim(),fee:Number(document.getElementById('courseFee').value||0),duration:document.getElementById('courseDuration').value.trim(),session:document.getElementById('courseSession').value.trim(),status:document.getElementById('courseStatus').value,description:document.getElementById('courseDescription').value.trim()};if(!course.name)return toast('Course name is required.');if(editId){const i=d.courses.findIndex(x=>x.id===editId);if(i>=0)d.courses[i]={...d.courses[i],...course}}else d.courses.push(course);save(d);document.getElementById('modal')?.remove();toast(editId?'Course updated.':'Course created successfully.');go('courses')}
function openCourseManager(id){const d=get(),c=d.courses.find(x=>x.id===id);if(!c)return;const classes=d.classes.filter(x=>x.courseId===id),students=d.students.filter(x=>x.courseId===id),recs=d.attendanceRecords.filter(r=>students.some(s=>s.id===r.studentId)),att=recs.length?Math.round(recs.reduce((a,r)=>a+Number(r.overall||0),0)/recs.length):0;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">COURSE MANAGEMENT</div><h2>${c.name}</h2><p class="muted">${c.code||''} · ${c.duration||'Duration not set'} · Course fee ${money(c.fee||0)}</p><div class="course-overview-grid"><div class="panel"><small>CLASSES</small><strong>${classes.length}</strong><span>Assigned class groups</span></div><div class="panel"><small>STUDENTS</small><strong>${students.length}</strong><span>Currently enrolled</span></div><div class="panel"><small>OVERALL ATTENDANCE</small><strong>${att}%</strong><span>Across this course</span></div></div><div class="course-class-list"><h3>Classes assigned to this course</h3>${classes.length?classes.map(x=>`<div class="course-class-row"><div><b>${x.name}</b><span>${x.students||0} students</span></div><strong>${Number(x.attendance||0)}%</strong><button class="linkbtn" onclick="openAttendanceRoster('${x.id}')">Attendance</button></div>`).join(''):`<div class="empty compact"><p>No classes assigned. Edit/create a class and choose this course.</p></div>`}</div><div class="modal-actions"><button class="btn" onclick="document.getElementById('modal').remove()">Close</button><button class="btn" onclick="openCourseEdit('${id}')">Edit course</button><button class="btn primary" onclick="document.getElementById('modal').remove();openClassModal('${id}')">+ Assign class</button></div></div></div>`)}
function openCourseEdit(id){document.getElementById('modal')?.remove();openCourseModal(id)}
function deleteCourse(id){const d=get(),c=d.courses.find(x=>x.id===id);if(!c)return;const usedStudents=d.students.some(s=>s.courseId===id),usedClasses=d.classes.some(x=>x.courseId===id);if(usedStudents||usedClasses)return toast('This course is assigned to students or classes. Reassign them before deleting the course.');if(!confirm(`Delete course ${c.name}?`))return;d.courses=d.courses.filter(x=>x.id!==id);save(d);toast('Course deleted.');go('courses')}

function adminClasses(){const d=get(),classes=d.classes||[];return `<div class="page-head"><div><div class="eyebrow">ACADEMIC STRUCTURE</div><h1>Classes</h1><p>Create class groups under a course. Attendance is tracked through students assigned to each class.</p></div><button class="btn primary" onclick="openClassModal()">+ Create class</button></div><div class="class-grid">${classes.map(x=>{const course=d.courses.find(c=>c.id===x.courseId);return `<div class="panel class-card"><span class="class-icon">▦</span><div class="course-code">${course?.code||'UNASSIGNED COURSE'}</div><h2>${x.name}</h2><div><b>${x.students??0} students</b><span>${x.subjects??0} subjects</span><span>${x.attendance??0}% attendance</span></div><div class="class-actions"><button class="linkbtn" onclick="openClassManager('${x.id}')">Manage class →</button><button class="danger-link" onclick="deleteClass('${x.id}')">Delete class</button></div></div>`}).join('')}</div>`}
function openClassManager(id){const d=get(),c=(d.classes||[]).find(x=>x.id===id);if(!c)return;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">CLASS MANAGEMENT</div><h2>${c.name}</h2><p class="muted">${c.students??0} students · ${c.subjects??0} subjects · ${c.attendance??0}% attendance</p><div class="manager-grid"><button class="manager-item" onclick="openRoster('${c.id}')"><strong>Students</strong><span>View / edit class roster</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Subjects','${c.id}')"><strong>Subjects</strong><span>Add or remove subjects</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Timetable','${c.id}')"><strong>Timetable</strong><span>Assign weekly periods</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Assignments','${c.id}')"><strong>Assignments</strong><span>Publish class assignments</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Homework','${c.id}')"><strong>Homework</strong><span>Send daily class work</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Exams & Date Sheets','${c.id}')"><strong>Exams & Date Sheet</strong><span>Create examinations</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Study Materials','${c.id}')"><strong>Study Materials</strong><span>Upload class resources</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Results','${c.id}')"><strong>Results</strong><span>Enter student results</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Announcements','${c.id}')"><strong>Announcements</strong><span>Publish class notices</span><b>Open →</b></button><button class="manager-item" onclick="openAcademicEditor('Events & Calendar','${c.id}')"><strong>Events & Calendar</strong><span>Create class events</span><b>Open →</b></button></div><div class="modal-actions"><button class="btn danger" onclick="deleteClass('${c.id}')">Delete class</button><button class="btn" onclick="document.getElementById('modal').remove()">Close</button><button class="btn primary" onclick="openClassEdit('${c.id}')">Edit class</button></div></div></div>`)}
function openRoster(id){const d=get(),c=(d.classes||[]).find(x=>x.id===id),students=(d.students||[]).filter(s=>s.classId===id);document.getElementById('modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">CLASS ROSTER</div><h2>${c?.name||'Class'}</h2><div class="roster-list">${students.length?students.map(st=>`<div><b>${st.name}</b><span>${st.admissionNo}</span><em>Active</em></div>`).join(''):`<div class="empty"><h3>No students assigned</h3><p>Add students and assign this class to populate the roster.</p></div>`}</div><div class="modal-actions"><button class="btn" onclick="document.getElementById('modal').remove()">Close</button></div></div></div>`)}
function openClassEdit(id){const d=get();const c=(d.classes||[]).find(x=>x.id===id);document.getElementById('modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">EDIT CLASS</div><h2>Update class</h2><form onsubmit="event.preventDefault();const d=get();const c=d.classes.find(x=>x.id==='${id}');c.name=document.getElementById('cname').value;c.courseId=document.getElementById('ccourse').value;c.students=Number(document.getElementById('cstudents').value);c.subjects=Number(document.getElementById('csubjects').value);c.attendance=Number(document.getElementById('cattendance').value);save(d);document.getElementById('modal').remove();toast('Class updated successfully.');go('classes')"><div class="form-grid"><label>Course<select id="ccourse"><option value="">Unassigned</option>${(d.courses||[]).map(x=>`<option value="${x.id}" ${c.courseId===x.id?'selected':''}>${x.name} · ${money(x.fee||0)}</option>`).join('')}</select></label><label>Class name<input id="cname" value="${c.name}"></label><label>Students<input id="cstudents" type="number" value="${c.students}"></label><label>Subjects<input id="csubjects" type="number" value="${c.subjects}"></label><label>Attendance %<input id="cattendance" type="number" min="0" max="100" value="${c.attendance}"></label></div><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">Save changes</button></div></form></div></div>`)}
function openClassModal(courseId=''){const d=get();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">NEW CLASS</div><h2>Create class</h2><form onsubmit="event.preventDefault();const d=get();d.classes=d.classes||[];const cid=document.getElementById('newclasscourse').value;d.classes.push({id:'CLS'+Date.now(),name:document.getElementById('newclass').value,courseId:cid||null,students:0,subjects:0,attendance:0});save(d);document.getElementById('modal').remove();toast('Class created and linked to the selected course.');go('classes')"><label>Course<select id="newclasscourse"><option value="">Unassigned</option>${(d.courses||[]).map(c=>`<option value="${c.id}" ${courseId===c.id?'selected':''}>${c.name} · ${money(c.fee||0)}</option>`).join('')}</select><small class="field-hint">Create a course first if this class belongs to a program.</small></label><label>Class name<input id="newclass" required placeholder="D.Pharm — First Year"></label><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">Create class</button></div></form></div></div>`)}
function deleteClass(id){const d=get(),c=(d.classes||[]).find(x=>x.id===id);if(!c)return;if(!confirm(`Delete ${c.name}? This removes the class and its local demo academic feed. Continue?`))return;d.classes=d.classes.filter(x=>x.id!==id);d.students=(d.students||[]).map(s=>s.classId===id?{...s,classId:''}:s);d.attendanceRecords=(d.attendanceRecords||[]).filter(x=>x.classId!==id);d.academic=(d.academic||[]).filter(x=>x.classId!==id);d.results=(d.results||[]).filter(x=>x.classId!==id);document.getElementById('modal')?.remove();save(d);toast('Class deleted.');go('classes')}

function adminFees(){const d=get();const allEntries=Object.entries(d.studentFees||{}).flatMap(([studentId,f])=>(f.entries||[]).map(e=>({...e,studentId})));const total=(d.students||[]).reduce((a,s)=>a+Number(studentFee(d,s.id).total||0),0),paid=allEntries.reduce((a,x)=>a+Number(x.amount||0),0),out=Math.max(total-paid,0),pct=total?paid/total*100:0;return `<div class="page-head"><div><div class="eyebrow">OFFLINE ACCOUNTS</div><h1>Fees & deposits</h1><p>Every student has an individually assigned course fee. Record offline deposits against that student.</p></div><button class="btn primary" onclick="openFeeModal()">+ Record deposit</button></div><div class="stats4"><div class="statcard"><small>Total billed</small><strong>${money(total)}</strong><span>${d.students.length} students</span></div><div class="statcard"><small>Recorded</small><strong>${money(paid)}</strong><span class="positive">${Math.round(pct)}%</span></div><div class="statcard"><small>Outstanding</small><strong>${money(out)}</strong><span class="warning">${Math.round(Math.max(100-pct,0))}%</span></div><div class="statcard"><small>Receipts</small><strong>${allEntries.length}</strong><span>Recorded offline</span></div></div><div class="panel table-panel"><table><thead><tr><th>Student</th><th>Course fee</th><th>Paid</th><th>Receipt</th><th>Amount</th><th>Method</th><th>Date</th><th>Actions</th></tr></thead><tbody>${allEntries.length?allEntries.map(x=>{const st=d.students.find(s=>s.id===x.studentId);const f=studentFee(d,x.studentId);return `<tr><td>${st?.name||'Unknown'}<small class="cell-sub">${st?.admissionNo||''}</small></td><td>${money(f.total)}</td><td>${money(feePaid(d,x.studentId))}</td><td>${x.id}</td><td><b>${money(x.amount)}</b></td><td>${x.method}</td><td>${x.date}</td><td><button class="linkbtn" onclick="openFeeEdit('${x.id}')">Edit</button><button class="danger-link inline" onclick="deleteFee('${x.id}')">Delete</button></td></tr>`}).join(''):`<tr><td colspan="8"><div class="empty"><div class="empty-icon">₹</div><h2>No fee deposits</h2><p>Record an offline deposit against a student.</p></div></td></tr>`}</tbody></table></div>`}
function openFeeModal(editId=''){const d=get(),allEntries=Object.entries(d.studentFees||{}).flatMap(([studentId,f])=>(f.entries||[]).map(e=>({...e,studentId}))),existing=editId?allEntries.find(x=>x.id===editId):null,selectedStudentId=existing?.studentId||d.students?.[0]?.id||'',assignedFee=selectedStudentId?Number(studentFee(d,selectedStudentId).total||0):0;document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">OFFLINE DEPOSIT</div><h2>${existing?'Edit':'Record'} student fee</h2><p class="muted">This records money already deposited with the institution. The course fee is assigned from the student's profile and is not created by recording a deposit.</p><form onsubmit="event.preventDefault();saveFee('${editId}')"><div class="form-grid"><label>Student<select id="fstudent" ${existing?'disabled':''} onchange="updateFeeAssignedAmount()">${(d.students||[]).map(st=>`<option value="${st.id}" ${selectedStudentId===st.id?'selected':''}>${st.name} · ${st.admissionNo}</option>`).join('')}</select></label><label>Assigned course fee<input id="fstudentfee" type="number" min="0" readonly value="${assignedFee}"><small class="field-hint">Set this in Students → Edit before recording a deposit.</small></label><label>Deposit amount<input id="famount" type="number" min="1" required value="${existing?.amount||''}" placeholder="25000"></label><label>Method<select id="fmethod"><option ${existing?.method==='Cash'?'selected':''}>Cash</option><option ${existing?.method==='Bank Deposit'?'selected':''}>Bank Deposit</option><option ${existing?.method==='Cheque'?'selected':''}>Cheque</option></select></label><label>Receipt ID<input id="freceipt" value="${existing?.id||'REC-'+Math.floor(10000+Math.random()*89999)}" ${existing?'':'readonly'}></label><label>Date<input id="fdate" type="date" value="${existing?new Date(existing.date).toISOString().slice(0,10):new Date().toISOString().slice(0,10)}"></label></div><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">${existing?'Save changes':'Record deposit'}</button></div></form></div></div>`) }
function updateFeeAssignedAmount(){const d=get(),id=document.getElementById('fstudent')?.value,input=document.getElementById('fstudentfee');if(input)input.value=id?Number(studentFee(d,id).total||0):0;}
function saveFee(editId){const d=get(),studentId=document.getElementById('fstudent').value,amount=Number(document.getElementById('famount').value);if(!studentId||!amount||amount<1)return toast('Select a student and enter a valid deposit amount.');d.studentFees=d.studentFees||{};d.studentFees[studentId]=d.studentFees[studentId]||{total:0,entries:[],assigned:false};const courseFee=Number(d.studentFees[studentId].total||0);if(courseFee<=0)return toast('Assign a course fee to this student first from Students → Edit.');const allEntries=Object.entries(d.studentFees).flatMap(([sid,f])=>(f.entries||[]).map(e=>({...e,studentId:sid}))),existingEntry=editId?allEntries.find(e=>e.id===editId):null,currentPaid=(d.studentFees[studentId].entries||[]).reduce((a,e)=>a+Number(e.amount||0),0),paidAfterEdit=currentPaid-(existingEntry&&existingEntry.studentId===studentId?Number(existingEntry.amount||0):0);if(paidAfterEdit+amount>courseFee)return toast('Deposit exceeds the remaining course fee of '+money(Math.max(courseFee-paidAfterEdit,0))+'.');const entry={id:document.getElementById('freceipt').value,date:new Date(document.getElementById('fdate').value+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}),amount,method:document.getElementById('fmethod').value,studentId};if(editId){for(const f of Object.values(d.studentFees)){const i=(f.entries||[]).findIndex(x=>x.id===editId);if(i>=0)f.entries[i]=entry}}else d.studentFees[studentId].entries.unshift(entry);save(d);document.getElementById('modal')?.remove();toast(editId?'Fee entry updated.':'Offline fee deposit recorded.');go('fees')}
function deleteFee(id){const d=get(),all=Object.entries(d.studentFees||{}).flatMap(([studentId,f])=>(f.entries||[]).map(e=>({...e,studentId}))),entry=all.find(x=>x.id===id);if(!entry)return;if(!confirm(`Delete fee receipt ${id} for ${money(entry.amount)}?`))return;const f=d.studentFees[entry.studentId];f.entries=f.entries.filter(x=>x.id!==id);save(d);toast('Fee entry deleted.');go('fees')}

function adminAttendance(){const d=get(),courses=d.courses||[];return `<div class="page-head"><div><div class="eyebrow">COURSE ATTENDANCE</div><h1>Attendance</h1><p>Track attendance by course, class and student. Course attendance is calculated from the students enrolled in that course.</p></div></div><div class="subject-grid">${courses.map(c=>{const sts=d.students.filter(s=>s.courseId===c.id),recs=d.attendanceRecords.filter(r=>sts.some(s=>s.id===r.studentId)),avg=recs.length?Math.round(recs.reduce((a,r)=>a+Number(r.overall||0),0)/recs.length):0,classes=d.classes.filter(x=>x.courseId===c.id);return `<div class="panel metric-card"><div><b>${c.name}</b><strong>${avg}%</strong></div><div class="progress"><i style="width:${avg}%"></i></div><small>${sts.length} students · ${classes.length} classes</small><button class="linkbtn" onclick="openCourseAttendance('${c.id}')">View course attendance →</button></div>`}).join('')}${!courses.length?`<div class="panel empty"><h2>No courses yet</h2><p>Create a course and assign classes/students first.</p></div>`:''}</div>`}
function openCourseAttendance(courseId){const d=get(),c=d.courses.find(x=>x.id===courseId),students=d.students.filter(s=>s.courseId===courseId),records=d.attendanceRecords.filter(r=>students.some(s=>s.id===r.studentId));document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">COURSE ATTENDANCE</div><h2>${c?.name||'Course'}</h2><p class="muted">Overall course attendance with each student's current class and attendance.</p><div class="attendance-simple-list">${students.map(st=>{const r=records.find(x=>x.studentId===st.id);const cls=d.classes.find(x=>x.id===st.classId);return `<div class="attendance-simple-row"><div><b>${st.name}</b><span>${st.admissionNo} · ${cls?.name||'Unassigned class'}</span></div><strong>${r?.overall??0}%</strong><button class="linkbtn" onclick="openAttendanceEdit('${st.id}','${st.classId}')">Edit</button></div>`}).join('')||`<div class="empty compact"><p>No students are assigned to this course yet.</p></div>`}</div><div class="modal-actions"><button class="btn" onclick="document.getElementById('modal').remove()">Close</button></div></div></div>`)}
function openAttendanceRoster(classId){const d=get(),c=(d.classes||[]).find(x=>x.id===classId),records=(d.attendanceRecords||[]).filter(r=>r.classId===classId);document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">ATTENDANCE ROSTER</div><h2>${c?.name||'Class'} attendance</h2><p class="muted">Only the student name, admission number and overall attendance are shown.</p><div class="attendance-simple-list">${records.map(r=>`<div class="attendance-simple-row"><div><b>${r.studentName}</b><span>${r.admissionNo}</span></div><strong>${r.overall}%</strong><button class="linkbtn" onclick="openAttendanceEdit('${r.studentId}','${classId}')">Edit</button></div>`).join('')}</div><div class="modal-actions"><button class="btn" onclick="document.getElementById('modal').remove()">Close</button></div></div></div>`)}
function openAttendanceEdit(studentId,classId){const d=get(),r=(d.attendanceRecords||[]).find(x=>x.studentId===studentId&&x.classId===classId);if(!r)return;document.getElementById('modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">ATTENDANCE EDITOR</div><h2>${r.studentName}</h2><p class="muted">Update the overall attendance percentage.</p><form onsubmit="event.preventDefault();const d=get(),r=d.attendanceRecords.find(x=>x.studentId==='${studentId}'&&x.classId==='${classId}');r.overall=Math.max(0,Math.min(100,Number(document.getElementById('overallatt').value)||0));save(d);document.getElementById('modal').remove();toast('Attendance updated.');go('attendance')"><label>Overall attendance %<input id="overallatt" type="number" min="0" max="100" value="${r.overall}"></label><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">Save attendance</button></div></form></div></div>`)}

function adminAcademics(){const cards=[['Timetable','Create and assign class schedules.'],['Assignments','Publish tasks and due dates.'],['Homework','Send daily homework by class.'],['Exams & Date Sheets','Publish examinations and rooms.'],['Study Materials','Upload notes, PDFs and lectures.'],['Results','Enter marks, grades and SGPA.'],['Announcements','Publish notices to selected classes.'],['Events & Calendar','Create events, holidays and deadlines.']];return `<div class="page-head"><div><div class="eyebrow">ACADEMIC MANAGEMENT</div><h1>Academics</h1><p>Publish and manage everything students see.</p></div><button class="btn" onclick="go('history')">View history ↺</button></div><div class="admin-control-grid">${cards.map(x=>`<div class="panel control-card"><span>${x[0]}</span><small>${x[1]}</small><div class="control-actions"><button class="btn primary" onclick="openAcademicEditor('${x[0]}')">Configure →</button><button class="btn" onclick="openHistory('${x[0]}')">History</button></div></div>`).join('')}</div>`}
function adminHistory(){const d=get(),items=(d.academic||[]).slice().sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0));return `<div class="page-head"><div><div class="eyebrow">CONTENT HISTORY</div><h1>History</h1><p>Review everything published or saved by the institution. Edit or delete records.</p></div></div><div class="panel table-panel"><div class="history-toolbar"><button class="btn" onclick="openHistory('all')">All</button><button class="btn" onclick="openHistory('Assignments')">Assignments</button><button class="btn" onclick="openHistory('Homework')">Homework</button><button class="btn" onclick="openHistory('Exams & Date Sheets')">Exams</button><button class="btn" onclick="openHistory('Study Materials')">Materials</button><button class="btn" onclick="openHistory('Events & Calendar')">Events</button><button class="btn" onclick="openHistory('Timetable')">Timetable</button></div><div id="historyList">${historyRows(items)}</div></div>`}
function historyRows(items){if(!items.length)return `<div class="empty panel"><div class="empty-icon">↺</div><h2>No history yet</h2><p>Published academic records will appear here.</p></div>`;return `<table><thead><tr><th>Type</th><th>Title</th><th>Class</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody>${items.map(x=>`<tr><td><span class="pill blue">${x.type}</span></td><td><b>${x.title||'Untitled'}</b><small class="cell-sub">${x.details||''}</small></td><td>${get().classes.find(c=>c.id===x.classId)?.name||'All classes'}</td><td>${x.status||'Published'}</td><td>${formatDate(x.createdAt)}</td><td><button class="linkbtn" onclick="openAcademicEditor('${x.type}','${x.classId||''}',${x.id})">Edit</button><button class="danger-link inline" onclick="deleteAcademic(${x.id})">Delete</button></td></tr>`).join('')}</tbody></table>`}
function openHistory(type='all'){const d=get(),items=(d.academic||[]).filter(x=>type==='all'||x.type===type).sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0));const box=document.getElementById('historyList');if(box)box.innerHTML=historyRows(items);else go('history')}
function deleteAcademic(id){const d=get(),item=(d.academic||[]).find(x=>x.id===id);if(!item)return;if(!confirm(`Delete ${item.type}: ${item.title||'Untitled'}?`))return;d.academic=d.academic.filter(x=>x.id!==id);save(d);toast('Academic record deleted.');go('history')}

function openAcademicEditor(type,classId='',editId=null){if(type==='Results')return openResultModal(classId);const d=get(),labels={Timetable:['Subject','Faculty'],Assignments:['Title','Subject'],Homework:['Subject','Task'],['Exams & Date Sheets']:['Exam name','Subject'],['Study Materials']:['Title','Subject'],Announcements:['Title','Category'],['Events & Calendar']:['Event title','Venue']}[type]||['Title','Details'];const existing=editId?(d.academic||[]).find(x=>x.id===Number(editId)):null;if(type==='Timetable')return openTimetableEditor(classId);document.getElementById('modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">ACADEMIC EDITOR</div><h2>${existing?'Edit':'Create'} ${type}</h2><p class="muted">${classId?'Editing content for the selected class.':'Create academic content and assign it to a class.'}</p><form onsubmit="event.preventDefault();saveAcademic('${type}',${existing?existing.id:'null'})"><div class="form-grid"><label>Class<select id="editorClass">${(d.classes||[]).map(c=>`<option value="${c.id}" ${c.id===classId?'selected':''}>${c.name}</option>`).join('')}</select></label><label>${labels[0]}<input id="editorTitle" required value="${existing?.title||''}" placeholder="${labels[0]}"></label><label>${labels[1]}<input id="editorDetails" value="${existing?.details||''}" placeholder="${labels[1]}"></label><label>Status<select id="editorStatus"><option ${existing?.status!=='Draft'?'selected':''}>Published</option><option ${existing?.status==='Draft'?'selected':''}>Draft</option></select></label><label class="file-upload">Attachment (PDF / image)<input id="editorFile" type="file" accept="application/pdf,image/*"><small>Upload a PDF or image. Students can preview and download it.</small></label></div><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">Save ${type}</button></div></form></div></div>`)}
function openTimetableEditor(classId=''){const d=get(),selectedClass=classId||d.classes?.[0]?.id||'',rows=(d.classSchedules?.[selectedClass]||d.schedule||[]).slice().sort((a,b)=>String(a.time||'').localeCompare(String(b.time||'')));document.getElementById('modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">TIMETABLE EDITOR</div><h2>Change class schedule</h2><p class="muted">Choose a class, then edit the weekly timetable. Saving publishes the schedule to students in this demo.</p><form onsubmit="event.preventDefault();saveTimetable()"><div class="form-grid"><label>Class<select id="ttClass">${(d.classes||[]).map(c=>`<option value="${c.id}" ${c.id===selectedClass?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Time<input id="ttTime" type="time" value="09:00"></label><label>Day<select id="ttDay"><option value="0">Monday</option><option value="1">Tuesday</option><option value="2">Wednesday</option><option value="3">Thursday</option><option value="4">Friday</option></select></label><label>Subject / activity<input id="ttSubject" required placeholder="Pharmacology"></label></div><div class="schedule-editor-list">${rows.map((r,ri)=>`<div><b>${r.time}</b>${r.days.map((x,di)=>`<button type="button" onclick="editTimetableCell(${ri},${di})">${x}</button>`).join('')}</div>`).join('')}</div><small class="field-hint">Tip: click a timetable cell above to load it into the editor, then change the subject and save.</small><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">Save schedule</button></div></form></div></div>`)}
function editTimetableCell(ri,di){const d=get(),classId=document.getElementById('ttClass')?.value||'',rows=Array.isArray(d.classSchedules?.[classId])?d.classSchedules[classId]:(d.schedule||[]),r=rows[ri];if(!r)return;document.getElementById('ttTime').value=r.time;document.getElementById('ttDay').value=di;document.getElementById('ttSubject').value=(r.days&&r.days[di]&&r.days[di]!=='—')?r.days[di]:'';window._ttEdit={ri,di,classId}}
function saveTimetable(){const d=get(),classId=document.getElementById('ttClass').value,time=document.getElementById('ttTime').value||'09:00',di=Number(document.getElementById('ttDay').value),subject=document.getElementById('ttSubject').value.trim();if(!subject)return toast('Enter a subject or activity.');const edit=window._ttEdit;d.classSchedules=d.classSchedules||{};d.classSchedules[classId]=Array.isArray(d.classSchedules[classId])?d.classSchedules[classId]:JSON.parse(JSON.stringify(d.schedule||[]));const rows=d.classSchedules[classId];if(edit&&edit.classId===classId&&rows[edit.ri]){rows[edit.ri].time=time;rows[edit.ri].days[edit.di]=subject;rows.sort((a,b)=>String(a.time||'').localeCompare(String(b.time||'')))}else{let row=rows.find(r=>r.time===time);if(!row){row={time,days:['—','—','—','—','—']};rows.push(row);rows.sort((a,b)=>a.time.localeCompare(b.time))}row.days[di]=subject}save(d);window._ttEdit=null;document.getElementById('modal')?.remove();toast('Timetable updated. Students will see the new schedule.');go('academics')}
function saveAcademic(type,editId=null){const d=get(),file=document.getElementById('editorFile')?.files?.[0];const finish=(attachment)=>{const classId=document.getElementById('editorClass').value;const selectedClass=(d.classes||[]).find(c=>String(c.id)===String(classId));const payload={type,classId,className:selectedClass?.name||'',courseId:selectedClass?.courseId||'',title:document.getElementById('editorTitle').value.trim(),details:document.getElementById('editorDetails').value.trim(),status:document.getElementById('editorStatus').value,attachment:attachment||null,createdAt:new Date().toISOString()};if(editId){const i=d.academic.findIndex(x=>x.id===Number(editId));if(i>=0){payload.id=d.academic[i].id;if(!attachment)payload.attachment=d.academic[i].attachment||null;payload.createdAt=d.academic[i].createdAt||payload.createdAt;d.academic[i]=payload}}else d.academic.push({id:Date.now(),...payload});save(d);document.getElementById('modal')?.remove();toast(`${type} ${editId?'updated':'saved'} successfully.`);go('history')};if(file){if(file.size>3.5*1024*1024)return toast('For this GitHub Pages demo, keep files under 3.5 MB. Supabase Storage removes this limit in production.');const reader=new FileReader();reader.onload=()=>finish({name:file.name,type:file.type,size:file.size,data:reader.result});reader.readAsDataURL(file)}else finish(null)}
function openResultModal(classId=''){const d=get(),students=(d.students||[]).filter(s=>!classId||s.classId===classId);document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal modal-wide"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">RESULT ENTRY</div><h2>Add result</h2><p class="muted">Select a student from the class and enter the academic result.</p><form onsubmit="event.preventDefault();saveResult()"><div class="form-grid"><label>Class<select id="resultClass">${(d.classes||[]).map(c=>`<option value="${c.id}" ${c.id===classId?'selected':''}>${c.name}</option>`).join('')}</select></label><label>Student<select id="resultStudent">${students.map(s=>`<option value="${s.id}">${s.name} · ${s.admissionNo}</option>`).join('')}</select></label><label>Subject<input id="resultSubject" required placeholder="Pharmaceutics"></label><label>Maximum marks<input id="resultMax" type="number" value="100" min="1"></label><label>Obtained marks<input id="resultObtained" type="number" min="0" required></label><label>Grade<select id="resultGrade"><option>A+</option><option>A</option><option>B+</option><option>B</option><option>C</option><option>F</option></select></label><label>Grade point<input id="resultPoint" type="number" min="0" max="10" step="0.1" value="9"></label><label>Status<select id="resultStatus"><option>Published</option><option>Draft</option></select></label></div><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">Save Result</button></div></form></div></div>`)}
function saveResult(){const d=get(),sid=document.getElementById('resultStudent').value,st=d.students.find(s=>s.id===sid);d.results.unshift({id:Date.now(),studentId:sid,studentName:st?.name||'',classId:document.getElementById('resultClass').value,subject:document.getElementById('resultSubject').value,max:Number(document.getElementById('resultMax').value),obtained:Number(document.getElementById('resultObtained').value),grade:document.getElementById('resultGrade').value,point:Number(document.getElementById('resultPoint').value),status:document.getElementById('resultStatus').value});save(d);document.getElementById('modal')?.remove();toast('Result saved.');go('academics')}

function render(){const app=document.getElementById('app');document.body.classList.toggle('dark',localStorage.theme==='dark');if(state.view==='landing')state.view='login';if(state.view==='login'){app.innerHTML=login(state.loginMode||'student');return}if(state.view==='student'&&!state.student){showLogin();return}if(state.view==='admin'&&!state.admin){showLogin('admin');return}app.innerHTML=shell(state.view==='admin');document.getElementById('screen').innerHTML=state.view==='admin'?adminScreen():studentScreen();if(localStorage.theme==='dark')document.body.classList.add('dark')}
function showLanding(){showLogin('student')}function showLogin(mode='student'){state.view='login';state.loginMode=mode;render()}async function doLogin(mode){
  const id=(document.getElementById('loginId')?.value||'').trim();
  const pass=document.getElementById('loginPass')?.value||'';
  if(supabaseClient) await hydrateFromCloud({preferCloud:true});
  const d=get();
  if(mode==='student'){
    const st=(d.students||[]).find(x=>String(x.admissionNo||'').trim().toLowerCase()===id.toLowerCase() && String(x.password||'')===pass);
    if(st){
      d.student={...st};
      save(d);
      sessionStorage.eduiqStudent='1';
      state.student=true; state.admin=false; state.view='student'; state.page='dashboard';
      render();
      if(st.mustChangePassword)setTimeout(()=>showFirstLoginPrompt('student'),80);
      return;
    }
  } else if(mode==='admin'){
    const stored=localStorage.getItem('adminPassword');
    const validPasswords=new Set(['1111111','EduIQ#Admin']);
    if(stored)validPasswords.add(stored);
    if(id.toLowerCase()==='admin' && validPasswords.has(pass)){
      sessionStorage.eduiqAdmin='1';
      state.admin=true; state.student=false; state.view='admin'; state.page='admin';
      // Push the PC's existing local data only when the cloud has no snapshot; otherwise keep cloud authoritative.
      if(supabaseClient){const row=await cloudRead();if(!row?.payload)await cloudWrite(get());}
      render();
      if(localStorage.getItem('adminMustChangePassword')!=='false')setTimeout(()=>showFirstLoginPrompt('admin'),80);
      return;
    }
  }
  toast('Invalid credentials. Check your ID and password.');
}
function openNotificationCenter(){const d=get(),isAdmin=state.view==='admin',student=currentStudentRecord(d);const items=isAdmin?[...(d.notifications||[]).map(x=>({...x,title:x.title||'Notification',meta:x.category||'Notice',time:x.time||'Now'})),...(d.announcements||[]).map(x=>({title:x.title||'Announcement',meta:x.category||'Announcement',time:x.createdAt||'Now'}))].slice(0,12):[...(d.notifications||[]).map(x=>({...x,title:x.title||'Notification',meta:x.category||'Notice',time:x.time||'Now'})),...(d.announcements||[]).filter(x=>!x.classId||x.classId===student?.classId).map(x=>({title:x.title||'Announcement',meta:x.category||'Announcement',time:x.createdAt||'Now'}))].slice(0,12);document.getElementById('notificationModal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back notification-back" id="notificationModal" onclick="if(event.target===this)this.remove()"><div class="modal notification-modal"><button class="modal-x" onclick="document.getElementById('notificationModal').remove()">×</button><div class="eyebrow">NOTIFICATIONS</div><h2>Updates</h2><p class="muted">${items.length?'Your latest institutional updates.':'You are all caught up.'}</p><div class="notification-list">${items.length?items.map(x=>`<div class="notification-item"><span class="notification-icon">◌</span><div><b>${esc(x.title)}</b><small>${esc(x.meta||'Notice')} · ${formatDate(x.time)}</small></div></div>`).join(''):`<div class="empty-inline"><b>No notifications yet.</b><span>New announcements and reminders will appear here.</span></div>`}</div><div class="modal-actions"><button class="btn" onclick="document.getElementById('notificationModal').remove()">Close</button></div></div></div>`)}
function showFirstLoginPrompt(role){const student=role==='student';document.body.insertAdjacentHTML('beforeend',`<div class="modal-back first-login-back" id="firstLoginModal"><div class="modal first-login-modal"><div class="first-login-icon">🔐</div><div class="eyebrow">FIRST SIGN-IN</div><h2>Change your password</h2><p class="muted">${student?'Your institution issued your initial password. For your security, change it before continuing.':'This is your first administrator sign-in. Set a new private password before continuing.'}</p><div class="modal-actions first-login-actions"><button class="btn" onclick="document.getElementById('firstLoginModal')?.remove();go('profile');setTimeout(()=>openPasswordModal('${role}'),120)">Change password</button><button class="linkbtn" onclick="document.getElementById('firstLoginModal')?.remove()">Later</button></div></div></div>`)}function openPasswordModal(role){const isStudent=role==='student';document.getElementById('modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-back" id="modal"><div class="modal security-modal"><button class="modal-x" onclick="document.getElementById('modal').remove()">×</button><div class="eyebrow">ACCOUNT SECURITY</div><h2>Change password</h2><p class="muted">Use a strong password you will remember. Your current password is required for verification.</p><form onsubmit="event.preventDefault();changePassword('${role}')"><label>Current password<div class="input-wrap"><input id="currentPassword" type="password" required autocomplete="current-password"></div></label><label>New password<div class="input-wrap"><input id="newPassword" type="password" minlength="8" required autocomplete="new-password"></div></label><label>Confirm new password<div class="input-wrap"><input id="confirmPassword" type="password" minlength="8" required autocomplete="new-password"></div></label><small class="field-hint">Minimum 8 characters. Avoid sharing your password with anyone.</small><div class="modal-actions"><button type="button" class="btn" onclick="document.getElementById('modal').remove()">Cancel</button><button class="btn primary">Update password</button></div></form></div></div>`)}function changePassword(role){const current=document.getElementById('currentPassword').value,newPass=document.getElementById('newPassword').value,confirm=document.getElementById('confirmPassword').value;if(newPass!==confirm)return toast('New passwords do not match.');if(newPass.length<8)return toast('Password must be at least 8 characters.');if(current===newPass)return toast('New password must be different from the current password.');if(role==='student'){const d=get(),me=currentStudentRecord(d);if(!me||me.password!==current)return toast('Current password is incorrect.');me.password=newPass;me.mustChangePassword=false;d.student={...me};save(d);document.getElementById('modal')?.remove();document.getElementById('firstLoginModal')?.remove();toast('Password changed successfully.');go('profile')}else{const stored=localStorage.adminPassword||'1111111';if(current!==stored)return toast('Current password is incorrect.');localStorage.adminPassword=newPass;localStorage.adminMustChangePassword='false';document.getElementById('modal')?.remove();document.getElementById('firstLoginModal')?.remove();toast('Administrator password changed successfully.');go('profile')}}function logout(){sessionStorage.clear();state.student=false;state.admin=false;state.page='dashboard';showLogin('student')}function toggleTheme(){document.body.classList.toggle('dark');localStorage.theme=document.body.classList.contains('dark')?'dark':'light'}
render();
prepareCloud().then(()=>{if(state.view!=='login'){render()}});
